def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    from collections import deque

    MOD = 1_000_000_007
    if n == 0:
        return 1
    if not banned:
        return pow(len(alphabet), n, MOD)

    char_id = {ch: i for i, ch in enumerate(alphabet)}
    size = len(alphabet)
    transitions = [[-1] * size]
    failure = [0]
    forbidden = [False]

    for word in banned:
        node = 0
        for ch in word:
            c = char_id[ch]
            if transitions[node][c] == -1:
                transitions[node][c] = len(transitions)
                transitions.append([-1] * size)
                failure.append(0)
                forbidden.append(False)
            node = transitions[node][c]
        forbidden[node] = True

    queue = deque()
    for c in range(size):
        child = transitions[0][c]
        if child == -1:
            transitions[0][c] = 0
        else:
            queue.append(child)

    while queue:
        node = queue.popleft()
        fallback = failure[node]
        forbidden[node] |= forbidden[fallback]

        for c in range(size):
            child = transitions[node][c]
            if child == -1:
                transitions[node][c] = transitions[fallback][c]
            else:
                failure[child] = transitions[fallback][c]
                queue.append(child)

    safe_nodes = [i for i in range(len(transitions)) if not forbidden[i]]
    index = {node: i for i, node in enumerate(safe_nodes)}
    m = len(safe_nodes)
    matrix = [[0] * m for _ in range(m)]

    for node in safe_nodes:
        row = matrix[index[node]]
        for target in transitions[node]:
            if not forbidden[target]:
                row[index[target]] += 1

    def multiply(a, b):
        result = [[0] * m for _ in range(m)]
        for i, a_row in enumerate(a):
            out = result[i]
            for k, value in enumerate(a_row):
                if value:
                    for j, other in enumerate(b[k]):
                        if other:
                            out[j] += value * other
            for j in range(m):
                out[j] %= MOD
        return result

    counts = [0] * m
    counts[index[0]] = 1

    while n:
        if n & 1:
            updated = [0] * m
            for i, count in enumerate(counts):
                if count:
                    for j, ways in enumerate(matrix[i]):
                        if ways:
                            updated[j] += count * ways
            counts = [value % MOD for value in updated]

        n >>= 1
        if n:
            matrix = multiply(matrix, matrix)

    return sum(counts) % MOD
